def pinch_objective(scene: Component) -> dict[str, Loss]:
    picked = cast(PickupScene, scene)
    speed = picked.contact_observations["relative_speed_m_s"].get().x[0]
    return {
        "thumb": picked.support["thumb"],
        "fingers": picked.support["fingers"],
        "opposition": picked.support["opposition"],
        "settle": Minimize(speed * speed),
    }

